"""Styles for Ceremyn's dashboard shell."""

SHELL_CSS = r"""
:root{--canvas:#070b12;--panel:#0e1520;--raised:#131d2a;--hover:#172536;--line:#233246;--bright:#31445d;--text:#e7edf6;--muted:#8a9aaf;--quiet:#5e6d82;--blue:#5ca7ff;--blue-bg:rgba(92,167,255,.14);--green:#4de0ad;--green-bg:rgba(77,224,173,.13);--red:#ff7979;--red-bg:rgba(255,121,121,.13);--amber:#ffc96b;--amber-bg:rgba(255,201,107,.13);--grid:rgba(120,158,198,.12);--sans:Manrope,system-ui,sans-serif;--mono:"DM Mono",ui-monospace,monospace}
:root[data-theme="light"]{--canvas:#f4f7fb;--panel:#fff;--raised:#edf3fa;--hover:#e4eef9;--line:#d9e2ed;--bright:#becddd;--text:#122033;--muted:#596c82;--quiet:#7b8b9e;--blue:#2379d8;--blue-bg:#e0eeff;--green:#087b5b;--green-bg:#dbf7ed;--red:#c64444;--red-bg:#ffe5e5;--amber:#996000;--amber-bg:#fff1d3;--grid:rgba(38,83,130,.12)}
*{box-sizing:border-box}html,body{min-height:100%;margin:0}body{background:var(--canvas);color:var(--text);font:13px/1.5 var(--sans);overflow-x:hidden}.num{font-family:var(--mono);font-variant-numeric:tabular-nums}.app{display:grid;grid-template-columns:84px minmax(0,1fr);min-height:100vh;background:radial-gradient(circle at 92% -8%,rgba(49,116,205,.18),transparent 28rem),var(--canvas)}
.sidebar{position:sticky;top:0;z-index:15;width:84px;height:100vh;display:flex;flex-direction:column;overflow:hidden;background:rgba(10,16,25,.9);border-right:1px solid var(--line);backdrop-filter:blur(18px);transition:width .22s}.sidebar:hover,.sidebar:focus-within{width:244px}.sidebar.collapsed{width:84px}.brand{height:84px;display:flex;align-items:center;gap:14px;padding:0 25px;border-bottom:1px solid var(--line);white-space:nowrap}.brand .mark{display:grid;place-items:center;flex:none;width:33px;height:33px;border:1px solid rgba(92,167,255,.65);border-radius:10px;background:var(--blue-bg);color:var(--blue);font-size:13px}.brand .name{font-size:15px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.brand .sub{margin-top:2px;color:var(--quiet);font:9px var(--mono);letter-spacing:.08em;text-transform:uppercase}.nav{display:flex;flex:1;flex-direction:column;gap:6px;padding:21px 12px}.nav:before{content:'Navigate';margin:0 12px 11px;color:var(--quiet);font:9px var(--mono);letter-spacing:.14em;text-transform:uppercase;opacity:0;transition:opacity .15s}.sidebar:hover .nav:before,.sidebar:focus-within .nav:before{opacity:1}.nav a{display:flex;align-items:center;gap:15px;height:44px;padding:0 14px;border:1px solid transparent;border-radius:10px;color:var(--muted);cursor:pointer;text-decoration:none;white-space:nowrap}.nav a:hover{background:var(--hover);color:var(--text)}.nav a.active{color:var(--text);background:var(--blue-bg);border-color:rgba(92,167,255,.25);box-shadow:inset 3px 0 0 var(--blue)}.nav a .ic{width:18px;height:18px;flex:none;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;stroke-width:1.8}.sidefoot{display:flex;align-items:center;justify-content:space-between;min-height:66px;padding:0 18px;border-top:1px solid var(--line);color:var(--quiet);font:10px var(--mono);white-space:nowrap}.collapse-btn,.menu-btn,.theme-btn{display:grid;place-items:center;width:32px;height:32px;border:1px solid var(--line);border-radius:9px;background:transparent;color:var(--muted);cursor:pointer}.collapse-btn{opacity:0}.sidebar:hover .collapse-btn{opacity:1}.collapse-btn:hover,.menu-btn:hover,.theme-btn:hover{background:var(--hover);color:var(--text);border-color:var(--bright)}
.main{min-width:0}.topbar{position:sticky;top:0;z-index:10;display:flex;align-items:center;gap:14px;height:84px;padding:0 34px;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--canvas) 82%,transparent);backdrop-filter:blur(18px)}.page-title{font-size:19px;font-weight:800;letter-spacing:-.03em}.page-title:before{content:'CEREMYN  /  ';color:var(--quiet);font:9px var(--mono);letter-spacing:.13em;vertical-align:middle}.spacer{flex:1}.menu-btn{display:none}.status-chips{display:flex;gap:7px}.chip{display:inline-flex;align-items:center;gap:7px;padding:6px 9px;border:1px solid var(--line);border-radius:8px;color:var(--muted);font:9px var(--mono)}.chip .dot{width:6px;height:6px;border-radius:50%;background:var(--quiet)}.chip.ok{color:var(--green)}.chip.ok .dot{background:var(--green);box-shadow:0 0 9px var(--green)}.chip.bad{color:var(--red)}.chip.bad .dot{background:var(--red)}.chip.warn{color:var(--amber)}.chip.warn .dot{background:var(--amber)}.clock{color:var(--muted);font-size:11px}.theme-btn{margin-left:3px}
.content{max-width:1680px;margin:0 auto;padding:30px 34px 52px;display:flex;flex-direction:column;gap:16px}.grid{display:grid;gap:14px}.kpis{grid-template-columns:repeat(auto-fit,minmax(190px,1fr))}.cols-2{grid-template-columns:repeat(auto-fit,minmax(360px,1fr))}.card{position:relative;min-width:0;padding:19px 20px;border:1px solid var(--line);border-radius:14px;background:var(--panel);box-shadow:0 16px 36px rgba(0,0,0,.12)}.card:hover{border-color:var(--bright)}.card h3,.section-label{margin:0 0 15px;color:var(--quiet);font:10px var(--mono);letter-spacing:.13em;text-transform:uppercase}.corner{display:none}.kpi{min-height:128px;overflow:hidden}.kpi:after{content:'';position:absolute;right:-16px;bottom:-17px;width:82px;height:82px;border:1px solid var(--line);border-radius:50%}.kpi:nth-child(1):before{content:'';position:absolute;inset:0;background:linear-gradient(125deg,var(--blue-bg),transparent 40%)}.kpi .label{position:relative;color:var(--quiet);font:9px var(--mono);letter-spacing:.11em;text-transform:uppercase}.kpi .val{position:relative;margin-top:13px;font:700 25px/1 var(--mono);letter-spacing:-.07em}.kpi .sub{position:relative;margin-top:9px;color:var(--muted);font-size:11px}.badge{display:inline-flex;padding:4px 8px;border:1px solid transparent;border-radius:6px;font:9px var(--mono);text-transform:uppercase}.badge.green{color:var(--green);background:var(--green-bg)}.badge.red{color:var(--red);background:var(--red-bg)}.badge.amber{color:var(--amber);background:var(--amber-bg)}.badge.blue,.badge.gold{color:var(--blue);background:var(--blue-bg)}.badge.gray{color:var(--muted);border-color:var(--line)}.pos{color:var(--green)}.neg{color:var(--red)}.neu{color:var(--text)}
.workspace-hero{position:relative;display:flex;align-items:flex-end;justify-content:space-between;gap:24px;min-height:238px;padding:34px;border:1px solid #2d4c70;border-radius:18px;overflow:hidden;background:linear-gradient(115deg,#11233b,#0d1624 57%,#0a111b)}.workspace-hero:after{content:'';position:absolute;right:-114px;top:-244px;width:400px;height:400px;border:1px solid rgba(115,180,255,.26);border-radius:50%;box-shadow:0 0 0 42px rgba(115,180,255,.035),0 0 0 84px rgba(115,180,255,.025)}.workspace-hero>div{position:relative;z-index:1}.hero-eyebrow{color:#91a9c4;font:10px var(--mono);letter-spacing:.13em;text-transform:uppercase}.workspace-hero h1{margin:14px 0 11px;font-size:42px;line-height:1.02;letter-spacing:-.06em}.workspace-hero h1 span{color:var(--blue)}.workspace-hero p{max-width:530px;margin:0;color:#a9bad0;font-size:13px}.hero-status{display:flex;align-items:center;gap:11px;min-width:220px;padding:14px 15px;border:1px solid rgba(142,190,243,.24);border-radius:11px;background:rgba(5,12,20,.42)}.hero-status b{display:block;font-size:11px}.hero-status small{display:block;margin-top:3px;color:#8ea2bb;font-size:10px}.pulse{width:8px;height:8px;border-radius:50%;background:var(--blue);box-shadow:0 0 0 6px rgba(92,167,255,.14)}
.risk-banner{display:flex;align-items:center;gap:13px;padding:15px 17px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.risk-banner.clear{background:var(--green-bg)}.risk-banner.attention{background:var(--red-bg)}.risk-icon{display:grid;place-items:center;width:29px;height:29px;border-radius:9px;background:var(--green);color:#062117;font-weight:800}.attention .risk-icon{background:var(--red)}.risk-banner-title{font-size:15px;font-weight:800}.risk-banner p{margin:3px 0 0;color:var(--muted);font-size:11px}.risk-banner .badge{margin-left:auto}.leader-name{font-size:27px;font-weight:800}.leader-metrics{display:flex;flex-wrap:wrap;gap:17px;margin:14px 0 10px;color:var(--muted);font-size:11px}.leader-metrics span{display:flex;gap:5px}.leader-metrics b{color:var(--text);font:700 17px var(--mono)}.chart{width:100%;height:270px}.tbl{width:100%;border-collapse:collapse;font-size:12px}.tbl th{padding:7px 10px;border-bottom:1px solid var(--line);color:var(--quiet);font:9px var(--mono);text-align:left;text-transform:uppercase}.tbl td{padding:12px 10px;border-bottom:1px solid var(--line)}.tbl tr:last-child td{border-bottom:0}.tbl tbody tr:hover{background:var(--hover)}.tbl td.r,.tbl th.r{text-align:right;font-variant-numeric:tabular-nums}.kv{display:flex;flex-direction:column}.kv .row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 1px;border-bottom:1px solid var(--line)}.kv .row:last-child{border-bottom:0}.kv .k{color:var(--muted);font-size:11px}.kv .v{font-size:11px;font-weight:700}.bar{height:5px;margin-top:8px;border-radius:5px;background:var(--raised)}.bar>span{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--blue),#8ac0ff)}.empty{padding:37px 20px;color:var(--quiet);text-align:center}.alert{display:flex;gap:10px;margin-bottom:8px;padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--raised)}.alert .sev,.gate .st{width:7px;height:7px;flex:none;margin-top:6px;border-radius:50%;background:var(--quiet)}.alert.critical .sev{background:var(--red)}.alert.warning .sev{background:var(--amber)}.gates{display:flex;flex-wrap:wrap;gap:7px}.gate{display:flex;align-items:center;gap:7px;padding:7px 9px;border:1px solid var(--line);border-radius:7px;background:var(--raised);font:10px var(--mono)}.gate.on .st{background:var(--green)}.input{width:100%;padding:11px 12px;border:1px solid var(--line);border-radius:9px;background:var(--raised);color:var(--text);font:12px var(--sans)}.input:focus{outline:none;border-color:var(--blue);box-shadow:0 0 0 3px var(--blue-bg)}.toolbar{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:13px}.pill{padding:7px 12px;border:1px solid var(--line);border-radius:7px;background:var(--panel);color:var(--muted);font:10px var(--mono);cursor:pointer}.pill.on{border-color:var(--blue);background:var(--blue-bg);color:var(--blue)}.btn{display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;border:1px solid var(--bright);border-radius:9px;background:transparent;color:var(--text);font:10px var(--mono);text-transform:uppercase;cursor:pointer}.btn:hover:not(:disabled){background:var(--hover)}.btn:disabled{opacity:.5}.btn-primary{border-color:var(--blue);background:var(--blue);color:#061321;font-weight:700}.log-line{display:grid;grid-template-columns:78px 64px 1fr;gap:10px;padding:9px 10px;border-bottom:1px solid var(--line)}.log-line .t,.log-line .k{color:var(--quiet)}
@media(max-width:820px){.app{grid-template-columns:1fr}.sidebar{position:fixed;width:244px;transform:translateX(-100%)}.sidebar.open{transform:none}.menu-btn{display:grid}.topbar{padding:0 18px}.page-title:before{display:none}.content{padding:22px 18px 40px}}@media(max-width:640px){.clock,#marketChip{display:none}.topbar{height:68px}.content{padding:16px 13px 32px}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.kpi{min-height:112px;padding:15px}.kpi .val{font-size:20px}.cols-2{grid-template-columns:1fr}.card{padding:16px}.workspace-hero{min-height:0;padding:25px 21px;align-items:flex-start;flex-direction:column}.workspace-hero h1{font-size:34px}.hero-status{width:100%}.tbl{min-width:560px}.card:has(.tbl){overflow-x:auto}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important}}
/* Structural workspace reset: horizontal command deck replaces the legacy side rail. */
.app{display:block}.commandbar{position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:26px;min-height:74px;padding:0 34px;border-bottom:1px solid var(--line);background:rgba(7,11,18,.92);backdrop-filter:blur(18px)}.wordmark{display:flex;align-items:center;gap:10px;color:var(--text);font-size:13px;font-weight:800;letter-spacing:.14em;text-decoration:none}.wordmark .mark{display:grid;place-items:center;width:28px;height:28px;border:1px solid var(--blue);border-radius:8px;color:var(--blue);font-size:11px}.commandbar .sidebar{position:static;display:flex;align-items:center;flex:1;width:auto;height:auto;overflow:visible;background:none;border:0;backdrop-filter:none;transition:none}.commandbar .sidebar:hover,.commandbar .sidebar:focus-within,.commandbar .sidebar.collapsed{width:auto}.commandbar .nav{display:flex;flex:1;flex-direction:row;align-items:center;gap:3px;padding:0}.commandbar .nav:before{display:none}.commandbar .nav a{height:34px;padding:0 9px;border-radius:7px;font-size:11px}.commandbar .nav a .ic{display:none}.commandbar .nav a.active{box-shadow:none}.command-status{display:flex;align-items:center;gap:12px}.commandbar .build-tag,.commandbar .collapse-btn{display:none}.topbar{height:90px;padding:0 34px;background:transparent;border:0}.topbar .eyebrow{margin-bottom:3px;color:var(--quiet);font:9px var(--mono);letter-spacing:.14em;text-transform:uppercase}.topbar .page-title{font-size:28px}.topbar .page-title:before{display:none}.market-strip{padding:8px 11px;border:1px solid var(--line);border-radius:8px;color:var(--muted);font:10px var(--mono)}
@media(max-width:980px){.commandbar{padding:0 18px;gap:14px}.commandbar .sidebar{position:fixed;top:74px;left:0;width:244px;height:calc(100vh - 74px);padding:14px;background:var(--panel);border-right:1px solid var(--line);transform:translateX(-100%)}.commandbar .sidebar.open{transform:none}.commandbar .nav{flex-direction:column;align-items:stretch}.commandbar .nav a .ic{display:block}.command-status .chip{display:none}.menu-btn{display:grid}.market-strip{display:none}}@media(max-width:640px){.commandbar{min-height:64px;padding:0 13px}.wordmark{font-size:12px}.command-status .clock{display:none}.topbar{height:76px;padding:0 14px}.topbar .page-title{font-size:24px}}
"""
